SELECT category, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, COUNT(CASE WHEN brand = 'Stark' THEN 1 END) AS stark_count, SUM(CASE WHEN category = 'Home' THEN 1 ELSE 0 END) AS home_count FROM products WHERE stock_qty != 124 AND brand NOT IN ('Stark', 'Globex', 'Initech') AND supplier_id IN (6, 17, 40) GROUP BY category, launch_cohort ORDER BY 4, stark_count;
